def test_report_envelope_matches_application_model_and_canonical_validator():
    import runpy

    import main
    from services.vision_analyzer import HotspotAnalysisResult

    application_fields = set(main.AnalysisResponse.model_fields) - set(HotspotAnalysisResult.model_fields)
    validator_path = ROOT / ".github/skills/heat-report-validation/scripts/validate_report.py"
    validator = runpy.run_path(str(validator_path))
    assert application_fields == REPORT_ENVELOPE
    assert application_fields == validator["REPORT_ENVELOPE_FIELDS"]
    assert application_fields == set(validator["REPORT_ENVELOPE_SCHEMA"])


