@pytest.mark.parametrize("call", ["await infer()", "aio.run(infer())", "aio.create_task(infer())",
                                 "await aio.gather(infer())", "pending = infer(); await pending",
                                 "await aio.to_thread(lambda: aio.run(infer()))"])
def test_coroutine_gate_accepts_import_aliases_and_deliberate_consumers(call):
    check_coroutines({"backend/producer.py": "async def analyze(): pass",
                      "backend/consumer.py": f"import asyncio as aio\nfrom producer import analyze as infer\nasync def route():\n    {call}\n"})


@pytest.mark.parametrize("call", ["infer()", "aio.gather(infer())", "await aio.to_thread(infer)",
                                 "await aio.to_thread(infer())"])
def test_coroutine_gate_rejects_discarded_or_threaded_coroutines(call):
    with pytest.raises(AssertionError, match="backend/consumer.py:4:"):
        check_coroutines({"backend/producer.py": "async def analyze(): pass",
                          "backend/consumer.py": f"import asyncio as aio\nfrom producer import analyze as infer\nasync def route():\n    {call}\n"})


def test_coroutine_gate_resolves_nested_async_definitions():
    with pytest.raises(AssertionError, match="backend/nested.py:3:"):
        check_coroutines({"backend/nested.py": "def factory():\n    async def analyze(): pass\n    analyze()\n"})


def test_coroutine_gate_reports_uncertain_parameter_shadowing():
    with pytest.warns(UserWarning, match="resolution is uncertain"):
        check_coroutines({"backend/shadow.py": "async def analyze(): pass\ndef consumer(analyze):\n    analyze()\n"})


