def test_alert_gate_rejects_history_claiming_dispatch_from_risk_alone(sources):
    rejected_mutation(sources, UI, 'dispatched = scan.get("alert_dispatched")', 'dispatched = scan.get("risk_level") == "CRITICAL"', check_alert_provenance, "History provenance drift")


def test_alert_gate_rejects_persistence_before_dispatch_completion(sources):
    rejected_mutation(sources, API, "await asyncio.to_thread(trigger_alert_if_critical, analysis_report)", "asyncio.to_thread(trigger_alert_if_critical, analysis_report)", check_alert_provenance, "Persistence ordering drift")